# Français — 7e AS, séries lettres modernes et lettres originelles (A et O) (IPN, 2025). Contenu tiré du manuel uniquement.
# Chaque texte du manuel = une leçon : le texte (image du manuel), compréhension (questions/réponses), production.
# + leçons de techniques d'expression (Partie II « Je m'exerce » et Partie III « Documents annexes »).
BOOK = "FR_7AO"

def F(page, y0, y1, x0=0.06, x1=0.94, cap=""):
    return {"page": page, "rect": [x0, y0, x1, y1], "caption": cap}

def S(h, lines=None, table=None):
    d = {"h": h, "lines": lines or []}
    if table: d["table"] = table
    return d

def T(title, pages, figs, objectives, intro, summary, points, qa, production, extra=None, apps=()):
    board = []
    for i, f in enumerate(figs):
        board.append({"h": "Le texte" + (f" ({i+1}/{len(figs)})" if len(figs) > 1 else ""), "lines": [], "fig": f})
    board.append({"h": "Compréhension", "lines": [], "table": [["Question", "Réponse"]] + [list(x) for x in qa]})
    if extra:
        board += extra
    board.append({"h": "Production", "lines": production})
    q, a = qa[0]
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": q, "a": a},
            "applications": [{"q": x, "a": y} for x, y in apps], "board": board}

def X(title, pages, objectives, intro, summary, points, board, app, apps=()):
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": app[0], "a": app[1]},
            "applications": [{"q": x, "a": y} for x, y in apps], "board": board}

# Les textes communs avec le manuel 7e C/D reprennent les leçons de FR_7CD (fonction R) avec les pages et images de ce manuel.
import copy as _copy, importlib.util as _ilu, os as _os
_sp = _ilu.spec_from_file_location("FR_7CD_base", _os.path.join(_os.path.dirname(__file__), "FR_7CD.py"))
_cd = _ilu.module_from_spec(_sp); _sp.loader.exec_module(_cd)

def R(key, title, pages, figs, extra_note=None):
    src = next(l for l in _cd.LESSONS if key in l["title"])
    l = _copy.deepcopy(src)
    l["title"] = title; l["match"] = [title]; l["pages"] = pages
    rest = [b for b in l["board"] if "fig" not in b and b["h"] != "Remarque"]
    l["board"] = [{"h": "Le texte" + (f" ({i+1}/{len(figs)})" if len(figs) > 1 else ""), "lines": [], "fig": f} for i, f in enumerate(figs)] + rest
    if extra_note:
        l["board"].append(S("Remarque", extra_note))
    return l

